#include "OpenMMContext.hpp"
#include "TopologyElements.hpp"
#include "World.hpp"

// Robosample top-level context. Constructed from Python as Context(base_name,
// seed); the Python subclass (context.py) adds the dihedral classifier and
// load_amber, which fills `systemTopology` in place.
//
// Owns the worlds (the Gibbs flexibility regimens), the replica temperature
// ladder, and the REX driver. World order defines the Gibbs sweep order, and
// per-atom Ground coordinates (nm) are the only currency passed between worlds.
class Context {
    public:
    Context(std::string baseName, std::uint32_t seed);

    // Bound to Python as `system_topology`. Filled in place by load_amber.
    SystemTopology systemTopology;

    // ---- modeling --------------------------------------------------------
    // Override a molecule's root attachment to Ground (default Free, set by
    // load_amber). Writes systemTopology.rootMobilities, which the worlds read.
    void setRootMobility(int moleculeIndex, RootMobility mobility);

    // Add a Cartesian world (pure OpenMM MD on device) or a robotic/torsional
    // world (internal-coordinate HMC). Both return a reference to the new world
    // so Python can chain .add_sampler(...). The model is built immediately
    // from the current systemTopology + root mobilities.
    World& addCartesianWorld();
    World& addRoboticWorld(const Selection& sel);

    // Add a DOCKING world. `ligandMoleculeIndices` lists which molecules are
    // ligands; their roots become Free (6 external DOF) and ALL their bonds stay
    // Rigid (rigid-body docking). Every other molecule is Welded to Ground and
    // rigid. Root mobility is thus a WORLD property here -- it is built from this
    // argument, NOT from systemTopology.rootMobilities, so the same system can
    // host a docking world and ordinary worlds at once. The binding-site centre
    // is the centroid of all non-ligand (receptor) atoms; pass a sphere radius
    // via add_sampler(...). Returns the world for chaining .add_sampler(...).
    World& addDockingWorld(const std::vector& ligandMoleculeIndices);


    // Per-bond mobility selection. `bonds` empty/None => every eligible
    // (non-ring, non-terminal) bond gets `mobility`; otherwise only the listed
    // (i,j) bonds do. Ring-closing bonds always remain Rigid.
    Selection buildFlexibilities(const std::optional<std::vector<std::pair>>& bonds,
                                 BondMobility mobility,
                                 bool flag);

    // ---- run -------------------------------------------------------------
    // Build the OpenMM system, set the replica temperature ladder, and seed
    // every replica with the reference coordinates. Empty list => single 300 K.
    void initialize(const std::vector& temperatures);

    // Replica-exchange driver: `equil` then `prod` rounds; each round runs a
    // Gibbs sweep over all worlds for every replica, attempts adjacent-replica
    // swaps, and writes outputs every `writeFreq` production rounds.
    void runREX(int equilRounds, int prodRounds, int writeFreq, bool verbose);

    // Enable multiple-timestep (r-RESPA) integration for the Cartesian world's
    // on-device OpenMM MD: slow forces (Nonbonded, GBSA, ...) are evaluated once
    // per outer step, fast bonded forces `innerSubsteps` times. No effect on the
    // torsional worlds (their forces are always the full sum). MUST be called
    // before initialize(). Forwards to OpenMMContext.
    void setMTS(bool enabled, int innerSubsteps);


    // ---- energy ingestion / validation (unchanged) ----------------------
    auto initializeOpenMM() -> bool;
    [[nodiscard]] auto calcOpenMMPotentialEnergy() -> double;
    [[nodiscard]] auto computePotentialEnergyByGroup()
        -> std::pair<double, std::vector>;

    [[nodiscard]] auto getBaseName() const -> const std::string& {
        return baseName;
    }
    [[nodiscard]] auto getSeed() const -> std::uint32_t {
        return seed;
    }
    [[nodiscard]] int numWorlds() const {
        return static_cast(worlds_.size());
    }

    private:
    double openmmPotential(const std::vector& coords);
    void writeOutputs(int replica, int round, bool verbose);

    // Refuse to start (or warn, if ROBO_ALLOW_BAD_START is set) when the input
    // geometry is non-finite or sterically clashing -- the docking world cannot
    // repair a frozen-receptor clash, so this would otherwise loop forever.
    void checkStartupGeometry();

    std::string baseName;
    std::uint32_t seed = 0;

    std::vector<std::unique_ptr> worlds_;         // heap so World& stays valid
    std::vector temperatures_;                   // one per replica
    std::vector<std::vector> replicaCoords_; // per replica, nm, OpenMM order
    int writeCounter_ = 0;
    std::vector dcdWriters_; // one trajectory per replica (baseName..dcd)
    std::vector dcdScratch_;      // interleaved xyz, nm->Angstrom, reused
    std::mt19937_64 rexRng_;
    std::uniform_real_distribution rexUniform_{0.0, 1.0};
};

#pragma once
/// DCDWriter.hpp — minimal, high-throughput C++17 DCD trajectory writer.
///
/// CHARMM-format DCD (compatible with VMD, MDTraj, GROMACS, etc.)
/// POSIX I/O, Linux only.  Single header, no dependencies.
///
/// Coordinate contract  (matches AlignedVecD layout):
///   pos[3*j + 0] = x_j,  pos[3*j + 1] = y_j,  pos[3*j + 2] = z_j
///
/// Compile with -O3 -march=native for AVX-2/512 gather+cvt in deinterleave().

#include 
#include 

#include 
#include 
#include 
#include 
#include 
#include 
#include 
#include 
#include 

namespace dcd {

/// Simulation box parameters.  Default: 1 Å cube, orthogonal.
struct Box {
    double sideA{1.0};
    double sideB{1.0};
    double sideC{1.0};
    double angleAlpha{90.0}; ///< angle between B and C (degrees)
    double angleBeta{90.0};  ///< angle between A and C (degrees)
    double angleGamma{90.0}; ///< angle between A and B (degrees)
};

/// Streaming DCD writer.
///
/// Open once, call append() per frame, let the destructor (or close()) patch
/// NFRAMES in the header.  Non-copyable, movable.
class Writer {
    public:
    /// @param path      Output path.
    /// @param numAtoms  Atoms per frame.
    /// @param withBox   Write CHARMM periodic-box EXTRA_BLOCK (default: true).
    Writer() noexcept = default;
    ~Writer() noexcept;

    Writer(const Writer&) = delete;
    auto operator=(const Writer&) -> Writer& = delete;

    Writer(Writer&&) noexcept;
    auto operator=(Writer&&) noexcept -> Writer&;

    /// Append one trajectory frame.
    ///
    /// @tparam Vec  Anything with .data() → const double* and size ≥ 3*numAtoms.
    ///              The interleaved layout x0 y0 z0 … xN yN zN is required.
    /// @param box   Periodic box for this frame. Ignored unless the writer was
    ///              opened withBox=true; supply the per-frame box under PBC so the
    ///              trajectory images correctly in analysis tools.
    template 
    auto append(const Vec& coords, const Box& box = Box{}) -> void {
        assert(fileFd_ >= 0 && "dcd::Writer: not initialized");
        if (withBox_) {
            fillBox(box);
        }
        deinterleaveCoords(coords.data());
        writeAll(frameBuf_.data(), static_cast(frameBytes_));
        ++frameCount_;
    }

    auto initialize(const std::string& path, int numAtoms, bool withBox = true) -> void;

    /// Flush, patch NFRAMES in the header, and close.  Idempotent.
    auto close() noexcept -> void;

    /// Number of frames written so far.
    [[nodiscard]] auto framesWritten() const noexcept -> int;

    private:
    //  DCD format constants

    /// Half-pi, used for the CHARMM cosine convention.
    static constexpr double kHalfPi{1.57079632679489661922};

    /// Pretend to be CHARMM v24 (non-zero value signals CHARMM format).
    static constexpr std::int32_t kCharmmVersion{24};

    /// Total header size for our fixed layout (CHARMM, 2 title lines, 32-bit).
    static constexpr int kHeaderBytes{276};

    /// File offset of the NFRAMES field (right after record-start + "CORD").
    static constexpr int kNframesOffset{8};

    /// File offset of the NSTEP field (= NFRAMES for istart=0, nsavc=1).
    static constexpr int kNstepOffset{20};

    //  State

    int fileFd_{-1};
    int numAtoms_{0};
    bool withBox_{false};
    int frameCount_{0};

    /// Single reusable output buffer.  Fortran record markers are pre-filled
    /// once in buildFrameTemplate(); only coordinate + box data change per frame.
    std::vector frameBuf_;

    /// Byte offsets of payload regions inside frameBuf_ (past their markers).
    int xOffset_{0};
    int yOffset_{0};
    int zOffset_{0};
    int ucOffset_{0};
    int frameBytes_{0};

    //  Setup

    /// Pre-fill Fortran record markers in frameBuf_ and record data offsets.
    ///
    /// Frame layout  (all counts in bytes):
    ///   [opt]  4 | 48 (6 × double box) | 4       ← CHARMM EXTRA_BLOCK
    ///          4 | numAtoms×4 (float X) | 4
    ///          4 | numAtoms×4 (float Y) | 4
    ///          4 | numAtoms×4 (float Z) | 4
    auto buildFrameTemplate() -> void;

    //  Hot path

    /// Convert box angles to CHARMM cosine convention and memcpy into frameBuf_.
    auto fillBox(const Box& box) noexcept -> void;

    /// Deinterleave x0y0z0…xNyNzN (double) into separate X/Y/Z planes (float)
    /// directly inside frameBuf_.  The stride-3 gather + narrowing cast
    /// vectorises to AVX-2/512 with -O3 -march=native.
    auto deinterleaveCoords(const double* __restrict__ src) noexcept -> void;

    //  I/O

    /// Retry wrapper around POSIX write() — handles EINTR and partial writes.
    auto writeAll(const void* buf, std::size_t size) -> void;

    /// Build the 276-byte DCD header into a stack-allocated array.
    [[nodiscard]] auto buildHeader() const -> std::array;

    /// Patch NFRAMES + NSTEP via pwrite(), then close() the descriptor.
    auto finalize() noexcept -> void;
};

} // namespace dcd

#pragma once

// ============================================================================
//  ForceBridge -- Robosample's DIRECT contract with OpenMM. No DuMM, no Simbody
//  subsystem, no NonBondedMappings gather.
//
//  Contract:
//    Robosample --> OpenMM : per-atom Cartesian positions in Ground (nm)
//    OpenMM     --> Robosample : per-atom Cartesian forces (kJ/mol/nm), which
//                   Robosample reduces to per-body spatial forces itself.
//  Atom order == OpenMM particle order == global/BFS order, so the transfer is
//  an index-free copy; the force->body scatter uses only model.atomBody[a].
//
//  HEADER-ONLY: every method is defined in-class (implicitly inline), so there
//  is exactly one definition across all translation units and no separate
//  ForceBridge.cpp / CMake entry is needed. (The previous declared-only methods
//  produced the `undefined symbol: ForceBridge::setAtomPositionsInGround` link
//  failure at import time.)
// ============================================================================

#include 

#include "OpenMMContext.hpp" // the existing OpenMM singleton (reused, not wrapped)
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "robot_math.hpp"

class ForceBridge {
    public:
    explicit ForceBridge(const RobotModel& model)
        : model_(model) {
    }

    // Robosample -> OpenMM: cache the Ground-frame positions in OpenMM particle
    // order. The actual context->setPositions happens inside OpenMMContext on
    // the next energy/force call (both of those take the position cache).
    void setAtomPositionsInGround(const RobotState& s) {
        const robo::Vec3* p = s.atomPosG();
        posCache_.resize(static_cast(model_.numAtoms));
        for (int a = 0; a < model_.numAtoms; ++a) {
            posCache_[a] = OpenMM::Vec3(p[a][0], p[a][1], p[a][2]);
        }
    }

    // Potential energy from OpenMM for the cached positions [kJ/mol].
    [[nodiscard]] robo::Real calcPotentialEnergy() const {
        return OpenMMContext::get().computePotentialEnergy(posCache_);
    }

    // OpenMM -> Robosample: read per-atom Cartesian forces and assemble per-body
    // spatial forces about each body's origin, expressed in Ground:
    //   bodyForceG[b].linear  += f_a
    //   bodyForceG[b].angular += (r_a - origin_b) x f_a
    // This is the exact reduction the articulated-body solver consumes; it
    // replaces the whole DuMM NonBondedMappings machinery.
    void getForcesFromOpenMM(RobotState& s) const {
        std::vector forces;
        OpenMMContext::get().evaluateForcesFromPositionsCache(posCache_, forces);

        robo::SpatialVec* BF = s.bodyForceG();
        for (int b = 0; b < model_.numBodies; ++b) {
            BF[b] = robo::SpatialVec(robo::Vec3(0), robo::Vec3(0));
        }
        // Generalized (joint) forces. calcUDot reads mobilityForce as the
        // applied per-DOF force (eps = f - H^T z). This model applies forces
        // ONLY as Cartesian atom forces (reduced into bodyForceG above); there
        // are no direct joint torques (Fixman unused), so the generalized force
        // is identically zero. It lives in the arena and is never written
        // elsewhere, so it MUST be cleared here every step -- otherwise
        // calcUDot reads uninitialized slab memory -> garbage udot -> NaN.
        // (Any future Fixman/biasing term should add into this cleared vector
        //  after evaluate() and before calcUDot.)
        robo::Real* mob = s.mobilityForce();
        for (int i = 0; i < model_.nu; ++i) {
            mob[i] = robo::Real(0);
        }
        const robo::Vec3* posG = s.atomPosG();
        const robo::Transform* X_GB = s.X_GB();
        for (int a = 0; a < model_.numAtoms; ++a) {
            // Virtual sites (mass == 0, e.g. the OPC/TIP4P M-site) carry no
            // independent DOF: OpenMM's getState(Forces) has ALREADY projected
            // the force computed at the site onto its real parent atoms (verify:
            // sum over REAL atoms reproduces the system net force / -dPE/dq to
            // machine precision, while the raw force still left in the site's own
            // slot makes the global sum nonzero). Reducing that leftover slot too
            // would DOUBLE-COUNT the site force -- here it would re-apply ~10^3
            // kJ/mol/nm per water at the M-site station, a non-conservative kick
            // that pumps the body's kinetic energy every step. Skip it; the
            // parents already carry the contribution.
            if (model_.atomMass[a] == robo::Real(0)) {
                continue;
            }
            const int b = model_.atomBody[a];
            const robo::Vec3 f(forces[a][0], forces[a][1], forces[a][2]);
            const robo::Vec3 r = posG[a] - X_GB[b].p(); // station in Ground, about body origin
            BF[b][1] += f;                              // linear (force)
            BF[b][0] += r % f;                          // angular (moment about origin); SimTK % == cross
        }
    }

    // One full force evaluation: positions then forces (Dynamics-stage realize).
    void evaluate(RobotState& s) {
        setAtomPositionsInGround(s);
        getForcesFromOpenMM(s);
    }

    void setVelocitiesToTemperature(double temperature, int seed) const {
        OpenMMContext::get().setVelocitiesToTemperature(temperature, seed);
    }

    // NCMC passthroughs (forward only ints; no SystemTopology coupling here).
    void enableAlchemy(int atomBegin, int atomEnd) const {
        OpenMMContext::get().enableAlchemy(atomBegin, atomEnd);
    }
    void setAlchemicalLambda(double lambdaInter) const {
        OpenMMContext::get().setAlchemicalLambda(lambdaInter);
    }

    bool integrateTrajectoryOnDevice(RobotState& s, int steps, robo::Real timestep) {
        setAtomPositionsInGround(s);                  // posCache_ <- s.atomPosG()
        OpenMMContext::get().setPositions(posCache_); // push to the live context
        const bool ok =
            OpenMMContext::get().integrateTrajectory(static_cast(steps), static_cast(timestep));
        OpenMMContext::get().getPositions(posCache_); // pull post-integration coords
        robo::Vec3* p = s.atomPosG();
        for (int a = 0; a < model_.numAtoms; ++a) {
            p[a] = robo::Vec3(posCache_[a][0], posCache_[a][1], posCache_[a][2]);
        }
        return ok;
    }

    private:
    const RobotModel& model_;
    std::vector posCache_; // OpenMM particle order, nm
};

#pragma once

// ============================================================================
//  MemoryArena — one aligned, contiguous memory slab with a bump pointer.
//
//  Purpose: give each World (live RobotState) and each Replica (compact
//  RobotState) ONE cache-line-aligned block, internally partitioned into SoA
//  arrays. No per-array malloc, no vector growth, no pointer chasing between
//  arrays at run time: every array's offset is fixed at build time.
//
//  OpenMP-future-compatible: every sub-array is 64-byte aligned, so later
//  `#pragma omp simd` / aligned AVX-512 loads are legal without re-layout.
//  We do NOT use OpenMP here.
//
//  Usage:
//    MemoryArena arena;
//    // Phase 1: reserve (no allocation yet) — record offsets.
//    auto qOff   = arena.reserve(nq);
//    auto posOff = arena.reserve(3 * nAtoms);
//    ...
//    arena.commit();                       // single aligned allocation
//    double* q   = arena.ptr(qOff);
//    double* pos = arena.ptr(posOff);
// ============================================================================

#include 
#include 
#include 
#include 

class MemoryArena {
    public:
    static constexpr std::size_t kAlign = 64; // cache line / AVX-512

    MemoryArena() = default;
    ~MemoryArena() {
        std::free(base_);
    }

    MemoryArena(const MemoryArena&) = delete;
    MemoryArena& operator=(const MemoryArena&) = delete;

    MemoryArena(MemoryArena&& o) noexcept
        : base_(o.base_)
        , size_(o.size_)
        , cursor_(o.cursor_)
        , committed_(o.committed_) {
        o.base_ = nullptr;
        o.size_ = 0;
        o.cursor_ = 0;
        o.committed_ = false;
    }
    MemoryArena& operator=(MemoryArena&& o) noexcept {
        if (this != &o) {
            std::free(base_);
            base_ = o.base_;
            size_ = o.size_;
            cursor_ = o.cursor_;
            committed_ = o.committed_;
            o.base_ = nullptr;
            o.size_ = 0;
            o.cursor_ = 0;
            o.committed_ = false;
        }
        return *this;
    }

    // A handle is just a byte offset into the slab (stable across the program).
    using Handle = std::size_t;

    // Reserve space for `count` T's, 64-byte aligned. Returns a handle.
    // Call only before commit().
    template 
    Handle reserve(std::size_t count) {
        if (committed_) {
            throw std::logic_error("MemoryArena::reserve after commit");
        }
        const std::size_t off = alignUp(cursor_, kAlign);
        cursor_ = off + count * sizeof(T);
        return off;
    }

    // Allocate the single aligned block. Idempotent guard.
    void commit() {
        if (committed_) {
            return;
        }
        size_ = alignUp(cursor_, kAlign);
        if (size_ == 0) {
            size_ = kAlign;
        }
        base_ = static_cast(std::aligned_alloc(kAlign, size_));
        if (base_ == nullptr) {
            throw std::bad_alloc();
        }
        committed_ = true;
    }

    // Typed pointer into the committed slab. Aligned to kAlign by construction.
    template 
    [[nodiscard]] T* ptr(Handle h) const noexcept {
        return reinterpret_cast(base_ + h);
    }

    [[nodiscard]] std::size_t bytes() const noexcept {
        return size_;
    }
    [[nodiscard]] bool committed() const noexcept {
        return committed_;
    }

    private:
    static std::size_t alignUp(std::size_t n, std::size_t a) noexcept {
        return (n + (a - 1)) & ~(a - 1);
    }

    std::byte* base_ = nullptr;
    std::size_t size_ = 0;
    std::size_t cursor_ = 0;
    bool committed_ = false;
};

// ----------------------------------------------------------------------------
//  Span — a non-owning typed view over a slab region. Lets engine code take
//  flat `double* __restrict` loops over arena arrays with no abstraction cost.
// ----------------------------------------------------------------------------
template 
struct SlabSpan {
    T* data = nullptr;
    std::size_t n = 0;
    [[nodiscard]] T& operator[](std::size_t i) const noexcept {
        return data[i];
    }
    [[nodiscard]] T* begin() const noexcept {
        return data;
    }
    [[nodiscard]] T* end() const noexcept {
        return data + n;
    }
    [[nodiscard]] std::size_t size() const noexcept {
        return n;
    }
};

